#include "networking.h"
#include <ArduinoJson.h>
#include <esp_timer.h>
constexpr char WIFI_SSID[]="CHANGE_ME",WIFI_PASSWORD[]="CHANGE_ME",LAPTOP_IP[]="192.168.1.10",DRONE_ID[]="wake-01";constexpr uint16_t TELEMETRY_PORT=5005,COMMAND_PORT=5007,CLOCK_PORT=5008;
void WakeNetworking::begin(){laptop_.fromString(LAPTOP_IP);WiFi.begin(WIFI_SSID,WIFI_PASSWORD);commandUdp_.begin(COMMAND_PORT);clockUdp_.begin(CLOCK_PORT);}
void WakeNetworking::update(){if(WiFi.status()!=WL_CONNECTED&&millis()-lastReconnectMs_>5000){lastReconnectMs_=millis();WiFi.reconnect();}handleClockSync();}
void WakeNetworking::handleClockSync(){int bytes=clockUdp_.parsePacket();if(!bytes)return;const uint64_t t2=(uint64_t)esp_timer_get_time();char input[256];int n=clockUdp_.read(input,255);if(n<=0)return;input[n]=0;StaticJsonDocument<256>request;if(deserializeJson(request,input)||String((const char*)request["type"])!="clock_sync_request")return;const uint64_t t3=(uint64_t)esp_timer_get_time();StaticJsonDocument<256>response;response["type"]="clock_sync_response";response["sequence"]=request["sequence"].as<uint32_t>();response["host_t1_ns"]=request["host_t1_ns"].as<uint64_t>();response["xiao_t2_us"]=t2;response["xiao_t3_us"]=t3;char out[256];size_t length=serializeJson(response,out);clockUdp_.beginPacket(clockUdp_.remoteIP(),clockUdp_.remotePort());clockUdp_.write((uint8_t*)out,length);clockUdp_.endPacket();}
void WakeNetworking::publishTelemetry(const TelemetryPacket&p){if(WiFi.status()!=WL_CONNECTED)return;StaticJsonDocument<1024>d;d["protocol_version"]=2;d["type"]="telemetry";d["drone_id"]=DRONE_ID;d["sequence"]=p.sequence;d["timestamp_us"]=p.timestampUs;d["imu_timestamp_us"]=p.imuTimestampUs;d["motors_timestamp_us"]=p.motorsTimestampUs;d["attitude_timestamp_us"]=p.attitudeTimestampUs;d["battery_timestamp_us"]=p.batteryTimestampUs;d["battery_v"]=p.batteryV;d["validity"]=p.validity;JsonArray a=d.createNestedArray("accel_body_g"),g=d.createNestedArray("gyro_body"),r=d.createNestedArray("attitude_rpy_rad"),m=d.createNestedArray("motors");for(int i=0;i<3;i++){a.add(p.accelG[i]);g.add(p.gyro[i]);r.add(p.attitudeRad[i]);}for(int i=0;i<4;i++)m.add(p.motors[i]);JsonObject h=d.createNestedObject("health");h["packet_hz"]=p.packetHz;h["imu_hz"]=p.imuHz;h["motor_hz"]=p.motorHz;h["attitude_hz"]=p.attitudeHz;h["battery_hz"]=p.batteryHz;h["msp_timeouts"]=p.mspTimeouts;h["wifi_rssi_dbm"]=WiFi.RSSI();char out[1024];size_t n=serializeJson(d,out);telemetryUdp_.beginPacket(laptop_,TELEMETRY_PORT);telemetryUdp_.write((uint8_t*)out,n);telemetryUdp_.endPacket();}
